-- Values shared by every other module.
--
-- theme.lua is generated by install/desktop/hyprland.sh from the installer's appearance answer
-- (and the palette is a projection of branding/tokens.json). Keeping the palette out of this
-- file is what makes "Hyprland, light" possible without a second copy of the desktop config.

mod = "SUPER"

local here = "/etc/parametral/hypr/"
theme = dofile(here .. "theme.lua")

palette = theme.palette
wallpaper = theme.wallpaper

function colour(name)
    return "rgba(" .. (palette[name] or palette.text) .. ")"
end
